<script>const b=document.querySelector('[data-site-menu]'),m=document.querySelector('[data-site-mobile-menu]');if(b&&m){b.addEventListener('click',()=>{const open=m.classList.toggle('open');b.setAttribute('aria-expanded',open?'true':'false');b.innerHTML=open?'<i class="fa-solid fa-xmark"></i>':'<i class="fa-solid fa-bars"></i>'});m.querySelectorAll('a').forEach(a=>a.addEventListener('click',()=>{m.classList.remove('open');b.setAttribute('aria-expanded','false');b.innerHTML='<i class="fa-solid fa-bars"></i>'}))}</script></body></html>
